{
  "qa": [
    {
      "question": "会议中提到的晚会具体举办时间是什么时候？",
      "answer": "会议确定晚会将于12月31日晚上6点开始入席。"
    },
    {
      "question": "如果天气寒冷，晚会是否需要调整为室内举办？",
      "answer": "会议讨论后决定晚会将固定在体育馆内举办，以避免因天气变化导致的户外活动风险。"
    },
    {
      "question": "晚会场地选择是否需要考虑外部租赁？",
      "answer": "会议认为学校现有体育馆面积足够，无需外部租赁，应优先利用校内场地进行布置和宣传。"
    }
  ]
}
